'use strict';
const SaveStore=(()=>{
 const bootAt=Date.now();
 let cloudAvailable=!(typeof location!=='undefined'&&(location.hostname||'').endsWith('.github.io')); 
 const key='mosswild-save-v2',backup=key+'-recovery';let problem='',blocked=false,meta={revision:0,linked:false},cloud=cloudAvailable?'Checking cloud…':'Device saves active · cloud backup is not connected on GitHub Pages',conflict=null,busy=false,lastCloud=0,lastRecovery=0,verified=false;
 function read(){let result=null;for(const k of [key,backup,'mosswild-save-v1']){try{const raw=localStorage.getItem(k);if(!raw)continue;const v=JSON.parse(raw);if(v.schema>2){blocked=true;problem='This save needs a newer game version. It has been kept unchanged.';return null;}result=MossSystems.unpack(v);if(k===key&&v.cloud)meta={revision:Number.isInteger(v.cloud.revision)?v.cloud.revision:0,linked:v.cloud.linked===true,account:typeof v.cloud.account==='string'?v.cloud.account:null};if(k!==key&&k!== 'mosswild-save-v1')problem='Recovered your previous local save.';break;}catch{problem='A damaged save was found. Checking recovery…';}}if(!result&&problem){blocked=true;problem='Local save could not be read. Export it from Saves before starting over.';}return result;}
 function write(s){if(blocked)return false;try{const old=localStorage.getItem(key);if(old&&Date.now()-lastRecovery>60000){try{MossSystems.unpack(old);localStorage.setItem(backup,old);lastRecovery=Date.now();}catch{}}localStorage.setItem(key,JSON.stringify({schema:2,savedAt:Date.now(),cloud:meta,state:s}));problem='';return true;}catch{problem='Device save failed. Download a backup in Saves.';return false;}}
 async function request(method,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch('/api/save',{method,signal:controller.signal,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});if(r.status===401||r.status===404){if(r.status===404)cloudAvailable=false;cloud='Cloud unavailable here · device saves active';return null;}if(!r.ok&&r.status!==409)throw Error('Cloud unavailable · will retry');return {status:r.status,data:await r.json()};}finally{clearTimeout(timer);}}
 async function sync(force=false){if(!cloudAvailable||busy||blocked||conflict||(!force&&Date.now()-lastCloud<30000))return;busy=true;try{
  if(!verified){const r=await request('GET');if(!r)return;verified=true;if(r.data.save&&(!meta.linked||r.data.account!==meta.account||r.data.revision!==meta.revision)){conflict=r.data;cloud='Choose which adventure to continue';if(typeof dialog!=='undefined'&&!dialog)saveMenu();return;}meta={revision:r.data.revision,linked:true,account:r.data.account};}
  const snapshot=MossSystems.clean(state),r=await request('PUT',{revision:meta.revision,account:meta.account,state:snapshot});if(!r)return;if(r.status===409){conflict=r.data;cloud='Another save is available · review in Saves';return;}meta.revision=r.data.revision;lastCloud=Date.now();cloud='Cloud saved '+new Date(lastCloud).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});write(state);
 }catch(e){cloud=e.name==='AbortError'?'Cloud connection timed out · will retry':e.message;}finally{busy=false;renderSaveBadge();}}
 async function choose(which){if(!conflict)return;if(which==='cloud'){if(!conflict.save)return;const s=MossSystems.clean(conflict.save);meta={revision:conflict.revision,linked:true,account:conflict.account};blocked=false;if(!write(s))return;blocked=true;location.reload();}else if(which==='device'){meta={revision:conflict.revision,linked:true,account:conflict.account};conflict=null;await sync(true);}}
 function recovery(){return MossSystems.unpack(localStorage.getItem(key+'-before-restore')||localStorage.getItem(backup));}
 function raw(){return localStorage.getItem(key)||localStorage.getItem('mosswild-save-v1');}
 function status(){return {problem,blocked,cloud,cloudAvailable,conflict,busy,lastCloud};}
 function replace(s){try{const old=localStorage.getItem(key);if(old)localStorage.setItem(key+'-before-restore',old);}catch{problem='Could not preserve your current save. Download a backup first.';return false;}blocked=false;meta={revision:0,linked:false};conflict=null;verified=false;const ok=write(MossSystems.clean(s));if(ok)blocked=true;return ok;}
 addEventListener('storage',e=>{if(e.key===key){try{if(JSON.parse(e.newValue)?.savedAt<=bootAt)return;}catch{}blocked=true;problem='This adventure changed in another tab. Reload this tab to continue safely.';if(typeof resetInput==='function')resetInput();if(typeof show==='function')saveMenu();}});
 return {read,write,sync,choose,status,replace,recovery,raw,key};
})();
